select v.* , 'approved'::moderation_status, now() from (values
('갑분싸','갑분싸',array['갑자기 분위기 싸해짐'],'갑자기 분위기가 어색하게 식는 상황을 뜻하는 말','2017년 유행했던 ''개꿀잼 몰카'' 영상 댓글에서 기대만큼 재미없을 때 ''갑자기 분위기 싸해짐ㄷㄷ''이라 쓰던 것이 줄어든 말이다. 트위치·아프리카TV 방송 채팅을 중심으로 퍼지며 2018년 초 방송에서도 급식체의 대표 사례로 소개됐다.','인터넷 방송 채팅 드립(2017)','어색해진 분위기를 셀프 디스할 때',null,'green','archived','phrase','image','beginner','funny',2017,jsonb_build_object('work','green','friends','green','family','green','sns','green')),
('롬곡옾눞(야민정음)','롬곡옾눞(야민정음)',array['폭풍눈물','댕댕이체'],'한글 자모를 비슷한 모양으로 바꿔 쓰는 놀이 문화','디시인사이드 국내야구 갤러리(야갤)에서 시작된 표기 놀이로, ''폭풍눈물''을 180도 뒤집으면 ''롬곡옾눞''처럼 보이는 것에서 착안했다. ''야갤''과 ''훈민정음''을 합쳐 야민정음이라 불리며 2018년 한글날 전후로 언론에도 크게 소개됐다.','디시인사이드 국내야구 갤러리(야갤)','글자 모양 말장난으로 웃음을 줄 때','기원이 극우 성향 커뮤니티라는 점은 알아둘 것','green','archived','phrase','image','normal','funny',2018,jsonb_build_object('work','green','friends','green','family','green','sns','green')),
('인정? 어인정','인정?-어인정',array['인정','노인정'],'동의한다는 뜻의 채팅 반응, 초성 ㅇㅈ로도 사용','아프리카TV 채팅 문화에서 시작된 표현으로, 상대 말에 공감할 때 ''인정? 어 인정''이라고 답하며 퍼졌다. 초성 ''ㅇㅈ''으로 줄여 쓰기도 했으며, 2017년 하반기부터는 ''동의? 어 보감'' 같은 말장난 변형이 등장했다.','아프리카TV 채팅 문화','상대 의견에 동의를 유쾌하게 표현할 때',null,'green','archived','phrase','image','beginner','funny',2017,jsonb_build_object('work','green','friends','green','family','green','sns','green')),
('혼모노','혼모노',array['혼모노 오타쿠'],'현실과 가상을 구분 못하는 민폐 오타쿠를 가리키는 은어','일본어로 ''진짜''를 뜻하는 혼모노(本物)가 한국에서는 현실과 가상을 혼동해 주변에 민폐를 끼치는 오타쿠를 가리키는 속어로 쓰였다. 2016년 영화 ''너의 이름은'' 개봉 후 극장에서 소란을 피우는 관객들이 화제가 되며 본격적으로 확산됐다.','일본어 ''本物''+''너의 이름은'' 개봉 논란(2016~2017)','특정 팬덤의 지나친 행동을 지적할 때 제한적으로','특정 취미 집단 전체를 비하하는 뉘앙스로 번질 수 있음','yellow','archived','phrase','image','normal','controversial',2017,jsonb_build_object('work','yellow','friends','green','family','yellow','sns','yellow')),
